SELECT COUNT(*)
FROM learning_record
WHERE user_id = #{userId}
  AND finished = #{finished}
  AND finish_time BETWEEN #{startTime} AND #{endTime}

SELECT lesson_id, COUNT(*) AS finished_count
FROM learning_record
WHERE user_id = #{userId}
  AND finished = #{finished}
  AND finish_time BETWEEN #{startTime} AND #{endTime}
GROUP BY lesson_id
